def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (everything after '+')
        if '+' in version:
            version_without_build = version.split('+')[0]
        else:
            version_without_build = version

        # Split pre-release (everything after '-' in the version without build)
        if '-' in version_without_build:
            core, prerelease = version_without_build.split('-', 1)
            prerelease_identifiers = prerelease.split('.')
        else:
            core = version_without_build
            prerelease_identifiers = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_sort_key(prerelease_identifiers):
        if prerelease_identifiers is None:
            # No pre-release sorts after pre-release
            return (1,)

        # Pre-release sorts before no pre-release
        key = [0]
        for identifier in prerelease_identifiers:
            if identifier.isdigit():
                # All-digit identifiers: (0, numeric_value)
                key.append((0, int(identifier)))
            else:
                # Non-digit identifiers: (1, string_value)
                key.append((1, identifier))
        return tuple(key)

    def version_sort_key(version):
        major, minor, patch, prerelease_identifiers = parse_version(version)
        return (major, minor, patch, prerelease_sort_key(prerelease_identifiers))

    # Stable sort to preserve input order for equal precedence
    return sorted(versions, key=version_sort_key)

